-- owner: WP-B.19
-- EMR-lite record (REC-3, REC-6; docs/spec/modules/asd-emr-lite-and-sharing/technical.md):
-- encounters (visits, calls, follow-ups) and attachments (scanned paper forms, referrals,
-- reports), plus the session and note links to an encounter.
--
-- Ids are generated by the service before encrypting (the row id is in the AEAD AAD,
-- KEY-3), so neither table has a column default for `id`.

-- ---------------------------------------------------------------- encounters (REC-3)

CREATE TABLE encounters (
    id                uuid        PRIMARY KEY,
    org_id            uuid        NOT NULL REFERENCES organizations (id),
    participant_id    uuid        NOT NULL,
    kind              text        NOT NULL CHECK (kind IN ('screening_visit', 'follow_up_visit',
                                                           'phone_call', 'home_visit', 'other')),
    occurred_at       timestamptz NOT NULL,
    clinician_id      uuid        REFERENCES users (id),
    -- Clear text: a short category-like reason, no clinical judgement (REC-3).
    reason            text        CHECK (char_length(reason) BETWEEN 1 AND 200),
    -- The clinician's summary, KEY-1 with AAD `encounters:summary_ct:{org}:{id}`.
    summary_ct        bytea,
    summary_key_id    uuid,
    status            text        NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
    follow_up_due_at  timestamptz,
    follow_up_done_at timestamptz,
    -- If-Match on PATCH (REC-4, SIGN-3).
    row_version       integer     NOT NULL DEFAULT 1 CHECK (row_version >= 1),
    created_by        uuid        NOT NULL REFERENCES users (id),
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz,
    CONSTRAINT encounters_id_org_key UNIQUE (id, org_id),
    CONSTRAINT encounters_participant_same_org_fk FOREIGN KEY (participant_id, org_id)
        REFERENCES participants (id, org_id),
    CONSTRAINT encounters_summary_key CHECK ((summary_ct IS NULL) = (summary_key_id IS NULL))
);
CREATE INDEX encounters_participant_occurred_idx
    ON encounters (org_id, participant_id, occurred_at DESC);
CREATE INDEX encounters_open_follow_up_idx
    ON encounters (org_id, follow_up_due_at) WHERE follow_up_done_at IS NULL;

-- A session or note documents at most one encounter of the same participant (checked by
-- the service). Deleting an encounter (erasure only) unlinks them.
ALTER TABLE sessions
    ADD COLUMN encounter_id uuid REFERENCES encounters (id) ON DELETE SET NULL;
CREATE INDEX sessions_encounter_idx ON sessions (encounter_id) WHERE encounter_id IS NOT NULL;
ALTER TABLE clinical_notes
    ADD COLUMN encounter_id uuid REFERENCES encounters (id) ON DELETE SET NULL;

-- ---------------------------------------------------------------- attachments (REC-6)

-- Bytes live in the blob store under `attachments/{org}/{participant}/{id}`, encrypted with
-- the org data key (AAD `attachments:blob:{org}:{id}`) before `put`; the file name is never
-- part of the key. `sha256` (of the plaintext), `blob_key` and `dek_key_id` are set when
-- the content is uploaded; until then the row is metadata only.
CREATE TABLE attachments (
    id             uuid        PRIMARY KEY,
    org_id         uuid        NOT NULL REFERENCES organizations (id),
    participant_id uuid        NOT NULL,
    encounter_id   uuid        REFERENCES encounters (id) ON DELETE SET NULL,
    kind           text        NOT NULL CHECK (kind IN ('paper_form', 'referral', 'report',
                                                        'photo_of_document', 'other')),
    file_name      text        NOT NULL CHECK (char_length(file_name) BETWEEN 1 AND 120
                                               AND file_name ~ '^[A-Za-z0-9._-]+$'),
    media_type     text        NOT NULL CHECK (media_type IN ('application/pdf', 'image/jpeg',
                                                              'image/png')),
    byte_size      integer     NOT NULL CHECK (byte_size BETWEEN 1 AND 10485760),
    sha256         bytea       CHECK (octet_length(sha256) = 32),
    blob_key       text,
    dek_key_id     uuid,
    uploaded_by    uuid        NOT NULL REFERENCES users (id),
    created_at     timestamptz NOT NULL DEFAULT now(),
    content_at     timestamptz,
    deleted_at     timestamptz,
    CONSTRAINT attachments_participant_same_org_fk FOREIGN KEY (participant_id, org_id)
        REFERENCES participants (id, org_id),
    CONSTRAINT attachments_content_complete CHECK (
        (sha256 IS NULL) = (blob_key IS NULL) AND (sha256 IS NULL) = (dek_key_id IS NULL)
        AND (sha256 IS NULL) = (content_at IS NULL))
);
CREATE INDEX attachments_participant_created_idx
    ON attachments (org_id, participant_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX attachments_encounter_idx ON attachments (encounter_id) WHERE encounter_id IS NOT NULL;

-- ---------------------------------------------------------------- application role grants

-- 0002's default privileges already give asd_app DML on tables created by the owner; grant
-- explicitly as well, so a database whose tables were created by another role (restore
-- into a fresh database, trap 17) still works.
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'asd_app') THEN
        RETURN;
    END IF;
    GRANT SELECT, INSERT, UPDATE, DELETE ON encounters, attachments TO asd_app;
    REVOKE TRUNCATE ON encounters, attachments FROM asd_app;
END;
$$;
